def admissible_primes(N: int, B: int) -> list[int]:
    sieve = bytearray([1]) * (B + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(B ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:: i] = bytearray(len(sieve[i * i:: i]))
    out: list[int] = []
    for p in (i for i in range(B + 1) if sieve[i]):
        r = N % p
        if p == 2 or r == 0 or pow(r, (p - 1) // 2, p) == 1:
            out.append(p)
    return out


if __name__ == "__main__":
    A = admissible_primes(103764863, 500)
    print(len(A), A[:15])  # Q(N,500) = 49

from fractions import Fraction


def psi_S(S: list[int], X: int) -> int:
    S = sorted(S)
    count = 0

    def rec(i: int, cur: int) -> None:
        nonlocal count
        if i == len(S):
            count += 1
            return
        v = cur
        while v <= X:
            rec(i + 1, v)
            v *= S[i]

    rec(0, 1)
    return count


def sign_flip(S: list[int], p: int, X: int) -> dict[str, object]:
    psi, psiq = psi_S(S, X), psi_S(S, X // p)
    psi2 = psi_S(S + [p], X)
    return {
        "certified": (len(S) + 1) * psiq >= psi,
        "exact": psi <= (len(S) + 1) * (psi2 - psi),
        "work_before": Fraction(len(S) + 1, psi),
        "work_after": Fraction(len(S) + 2, psi2),
    }


if __name__ == "__main__":
    print(sign_flip([2, 3], 5, 100))  # certified; 3/20 -> 2/17

def first_dependency(vectors: list[int]) -> tuple[int, set[int]]:
    basis: dict[int, tuple[int, set[int]]] = {}
    for k, v0 in enumerate(vectors, start=1):
        v, comb = v0, {k - 1}
        while v:
            h = v.bit_length() - 1
            if h not in basis:
                break
            bv, bc = basis[h]
            v, comb = v ^ bv, comb ^ bc
        if v == 0:
            assert len(basis) == k - 1  # prefix-rank identity
            return k, comb
        basis[v.bit_length() - 1] = (v, comb)
    raise ValueError("no dependency yet")


if __name__ == "__main__":
    tri = [0b011, 0b110, 0b101]  # triangle rows over GF(2)
    print(first_dependency(tri))  # (3, {0, 1, 2})

import random


def det_int(M: list[list[int]]) -> int:
    M = [r[:] for r in M]
    n, sign, prev = len(M), 1, 1
    for k in range(n - 1):
        if M[k][k] == 0:
            s = next((i for i in range(k + 1, n) if M[i][k]), None)
            if s is None:
                return 0
            M[k], M[s] = M[s], M[k]
            sign = -sign
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) // prev
        prev = M[k][k]
    return sign * M[-1][-1]


def rank_gf2(M: list[list[int]]) -> int:
    basis: dict[int, int] = {}
    for row in M:
        v = sum((a & 1) << j for j, a in enumerate(row))
        while v:
            h = v.bit_length() - 1
            if h in basis:
                v ^= basis[h]
            else:
                basis[h] = v
                break
    return len(basis)


def full_rank_over_Q(M: list[list[int]]) -> bool:
    return det_int(M) != 0


def discriminating_suite(n: int, m: int, seed: int = 0) -> list[list[list[int]]]:
    rng = random.Random(seed)
    suite = [[[1, 1, 0], [0, 1, 1], [1, 0, 1]]] if n == 3 else []
    while len(suite) < m:
        M = [[rng.randint(-2, 2) for _ in range(n)] for _ in range(n)]
        d = det_int(M)
        if d != 0 and d % 2 == 0:
            suite.append(M)
    return suite


if __name__ == "__main__":
    suite = discriminating_suite(3, 10)
    caught = all(full_rank_over_Q(M) != (rank_gf2(M) == 3) for M in suite)
    print("every matrix catches the Q-rank mutant:", caught)

import math
from itertools import combinations


def pair_partials(full: list[int], partials: list[tuple[int, int]], Q: int) -> tuple[list[int], bool]:
    rep: dict[int, int] = {}
    combined = list(full)
    for i, (s, l) in enumerate(partials):
        if l in rep:
            combined.append(s * l * partials[rep[l]][0] * l)
        else:
            rep[l] = i
    D = len(rep)
    return combined, len(full) + (len(partials) - D) > Q


if __name__ == "__main__":
    comb, guaranteed = pair_partials([6], [(2, 101), (3, 101), (6, 101)], Q=2)
    print(comb, guaranteed)
    for r in range(1, len(comb) + 1):
        for T in combinations(comb, r):
            P = math.prod(T)
            if math.isqrt(P) ** 2 == P:
                print("square:", T, "=", math.isqrt(P), "^2")
                raise SystemExit

