def primes_upto(n: int) -> list[int]:
    is_p = bytearray([1]) * (n + 1)
    is_p[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if is_p[i]:
            is_p[i * i:: i] = bytearray(len(is_p[i * i:: i]))
    return [i for i in range(n + 1) if is_p[i]]


def is_square_mod(a: int, p: int) -> bool:
    a %= p
    return a == 0 or p == 2 or pow(a, (p - 1) // 2, p) == 1


def smooth_over(v: int, S: Iterable[int]) -> bool:
    for p in S:
        while v % p == 0:
            v //= p
    return v == 1


def paid_work_curve(N: int, B: int, window: int = 400000) -> list[tuple[int, int]]:
    A = [p for p in primes_upto(B) if is_square_mod(N, p)]
    a = math.isqrt(N) + 1
    smooth = []  # (position, largest admissible prime used)
    for k in range(window):
        v = (a + k) ** 2 - N
        big = 0
        for p in A:
            if v % p == 0:
                while v % p == 0:
                    v //= p
                big = p
            if v == 1:
                break
        if v == 1:
            smooth.append((k + 1, big))
    out = []
    for q in range(max(3, len(A) // 3), len(A) + 1):
        lim, c = A[q - 1], 0
        for pos, big in smooth:
            if big <= lim:
                c += 1
                if c == q + 1:
                    out.append((q, pos))
                    break
    return out


if __name__ == "__main__":
    N = 103764863
    fig, ax = plt.subplots(figsize=(8, 4.5))
    for B in (300, 400, 600):
        pts = paid_work_curve(N, B)
        ax.plot([q for q, _ in pts], [p for _, p in pts], marker="o", ms=3, label=f"B = {B}")
    ax.set_xlabel("number of columns q (smallest admissible primes kept)")
    ax.set_ylabel("sieve positions scanned to reach q+1 relations")
    ax.set_title("Paid sieve work DECREASES as the factor base grows (N = 103764863)")
    ax.set_yscale("log")
    ax.legend()
    ax.grid(alpha=0.3)
    plt.tight_layout()
    plt.savefig("paid_work_vs_q.png", dpi=150)
