import random
import matplotlib.pyplot as plt


def rank_gf2(rows: list[int]) -> int:
    basis: dict[int, int] = {}
    for v in rows:
        while v:
            h = v.bit_length() - 1
            if h in basis:
                v ^= basis[h]
            else:
                basis[h] = v
                break
    return len(basis)


def k_success(rows: list[int]) -> int:
    for k in range(1, len(rows) + 1):
        if rank_gf2(rows[:k]) < k:
            return k
    raise ValueError


if __name__ == "__main__":
    rng = random.Random(0)
    Q = 40
    fig, ax = plt.subplots(figsize=(8, 4.5))
    for density in (0.05, 0.1, 0.3):
        ks = []
        for _ in range(400):
            rows = [sum(1 << j for j in range(Q) if rng.random() < density) for _ in range(2 * Q)]
            k = k_success(rows)
            assert k == rank_gf2(rows[:k]) + 1 <= Q + 1
            ks.append(k)
        ax.hist(ks, bins=range(1, Q + 3), alpha=0.5, label=f"bit density {density}")
    ax.axvline(Q + 1, color="k", ls="--", label="sharp bound Q+1")
    ax.set_xlabel("k_success (first dependent prefix)")
    ax.set_ylabel("frequency")
    ax.set_title("k_success = rank(prefix)+1 <= Q+1  (Q = 40, random sparse GF(2) vectors)")
    ax.legend()
    plt.tight_layout()
    plt.savefig("k_success_hist.png", dpi=150)
    plt.show()
